    """Return elbow and arm directions for a one-cell-thick orthogonal L."""
    cells = comp
    rows = Counter(r for r, c in cells)
    cols = Counter(c for r, c in cells)
    best = None
    for r, nr in rows.items():
        for c, nc in cols.items():
